seen = {}
for row in W:
    seen[row[0]] = row  # later duplicates win (same text)
out = {l: {en: row[i + 1] for en, row in seen.items()} for i, l in enumerate(LANGS)}
data = json.dumps(out, ensure_ascii=False, separators=(",", ":"))
for p in ["app/src/main/assets/i18n.json", "ios/Movio/i18n.json", "web/i18n.json"]:
    full = os.path.join(R, "..", p)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    open(full, "w", encoding="utf-8").write(data)
print(len(seen), "phrases written")
